#!/usr/bin/env python3
"""Genera il sito statico in dist/ da data/bandi.json."""
import json, html, pathlib, datetime
R = pathlib.Path(__file__).resolve().parent.parent
D = R / "dist"; D.mkdir(exist_ok=True); (D / "bando").mkdir(exist_ok=True)
B = json.loads((R / "data/bandi.json").read_text(encoding="utf-8"))
oggi = datetime.date.today().isoformat()
B = [b for b in B if not b["scadenza"] or b["scadenza"] >= oggi]  # archivia scaduti
B.sort(key=lambda b: b["scadenza"] or "9999")
e = html.escape
CSS = """body{font-family:system-ui,sans-serif;margin:0;color:#1d2433;background:#f6f7fb}header{background:#0b5cad;color:#fff;padding:14px 20px}header a{color:#fff;margin-right:14px;text-decoration:none}main{max-width:980px;margin:auto;padding:18px}.card{background:#fff;border-radius:10px;padding:14px 16px;margin:10px 0;box-shadow:0 1px 3px #0002}.tag{display:inline-block;background:#e6eefb;color:#0b5cad;border-radius:6px;padding:1px 7px;font-size:12px;margin-right:4px}.sp{border:2px dashed #999;text-align:center;padding:22px;color:#666;background:#fff;border-radius:10px;margin:14px 0}select{padding:6px;margin-right:8px}footer{font-size:13px;color:#555;padding:20px;max-width:980px;margin:auto}.warn{background:#fff6dd;padding:10px;border-radius:8px;font-size:14px}"""
def page(title, body, pre=""):
    return f"""<!doctype html><html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} – IncentiviPerTe</title><style>{CSS}</style></head><body><header><b>IncentiviPerTe</b> &nbsp; <a href="{pre}index.html">Bandi</a><a href="{pre}toscana.html">Toscana</a><a href="{pre}umbria.html">Umbria</a><a href="{pre}disclaimer.html">Disclaimer</a><a href="{pre}privacy.html">Privacy</a></header><main>{body}</main><footer>Contatti: <a href="mailto:davoglio@mail.grokbot.com">davoglio@mail.grokbot.com</a> · Informazioni indicative: fa fede esclusivamente il bando ufficiale. Nessuna consulenza. · <a href="{pre}disclaimer.html">Disclaimer</a> · <a href="{pre}privacy.html">Privacy</a></footer></body></html>"""
SP = '<div class="sp"><b>Spazio disponibile</b><br>Spazio sponsor per commercialisti, consulenti, banche e software.</div>'
def card(b, pre=""):
    t = "".join(f'<span class="tag">{e(x)}</span>' for x in [b["regione"]] + b["destinatari"])
    return f'<div class="card" data-reg="{e(b["regione"])}" data-dest="{e("|".join(b["destinatari"]))}" data-scad="{b["scadenza"] or "9999-12-31"}"><h3><a href="{pre}bando/{b["id"]}.html">{e(b["titolo"])}</a></h3>{t}<p>{e(b["sintesi"])}</p><small><b>Scadenza:</b> {e(b["nota_scadenza"])} · <b>Ente:</b> {e(b["ente"])}</small></div>'
dest = sorted({d for b in B for d in b["destinatari"]})
filt = f"""<p><select id="r"><option value="">Tutte le aree</option><option>Nazionale</option><option>Toscana</option><option>Umbria</option></select><select id="d"><option value="">Tutti i destinatari</option>{''.join(f'<option>{e(x)}</option>' for x in dest)}</select><select id="s"><option value="">Qualsiasi scadenza</option><option value="30">Entro 30 giorni</option><option value="90">Entro 90 giorni</option><option value="none">Senza scadenza fissa</option></select></p>
<script>function f(){{const r=R.value,d=Dd.value,s=S.value,now=new Date();document.querySelectorAll('.card').forEach(c=>{{let ok=(!r||c.dataset.reg==r)&&(!d||c.dataset.dest.split('|').includes(d));const sc=c.dataset.scad;if(s=='none')ok=ok&&sc.startsWith('9999');else if(s){{ok=ok&&!sc.startsWith('9999')&&(new Date(sc)-now)/864e5<=+s}}c.style.display=ok?'':'none'}})}}const R=document.getElementById('r'),Dd=document.getElementById('d'),S=document.getElementById('s');[R,Dd,S].forEach(x=>x.onchange=f)</script>"""
(D/"index.html").write_text(page("Bandi e incentivi per startup e PMI", f'<h1>Bandi e incentivi per startup e PMI</h1><p>Raccolta gratuita di bandi aperti nazionali e regionali (focus Toscana e Umbria). {len(B)} bandi, ultimo aggiornamento {max(b["ultimo_controllo"] for b in B)}.</p><p class="warn">Verifica sempre requisiti e scadenze sul sito ufficiale.</p>{SP}{filt}{"".join(card(b) for b in B)}'), encoding="utf-8")
for reg in ["Toscana", "Umbria"]:
    L = [b for b in B if b["regione"] == reg]
    (D/f"{reg.lower()}.html").write_text(page(f"Bandi {reg}", f'<h1>Bandi {reg}</h1>{SP}{"".join(card(b) for b in L)}<p>Vedi anche gli incentivi nazionali in <a href="index.html">home</a>.</p>'), encoding="utf-8")
for b in B:
    body = f'<p><a href="../index.html">← Tutti i bandi</a></p><div class="card"><h1>{e(b["titolo"])}</h1><p><b>Ente:</b> {e(b["ente"])}<br><b>Area:</b> {e(b["regione"])}<br><b>Destinatari:</b> {e(", ".join(b["destinatari"]))}<br><b>Scadenza:</b> {e(b["nota_scadenza"])}</p><p>{e(b["sintesi"])}</p><p><a href="{e(b["url"])}" rel="noopener" target="_blank"><b>Vai al bando ufficiale →</b></a></p><p><small>Ultimo controllo sulla fonte ufficiale: {b["ultimo_controllo"]}</small></p></div>{SP}'
    (D/"bando"/f'{b["id"]}.html').write_text(page(b["titolo"], body, "../"), encoding="utf-8")
(D/"disclaimer.html").write_text(page("Disclaimer", "<h1>Disclaimer</h1><p>IncentiviPerTe è un servizio informativo gratuito e indipendente, non affiliato ad alcun ente pubblico. Le schede sono sintesi indicative redatte da fonti ufficiali e possono contenere errori o non essere aggiornate. Fa fede esclusivamente il testo del bando pubblicato dall'ente. Le informazioni non costituiscono consulenza fiscale, legale o finanziaria. Gli spazi sponsor sono pubblicità e sono sempre segnalati come tali.</p>"), encoding="utf-8")
(D/"privacy.html").write_text(page("Privacy", "<h1>Informativa privacy (base)</h1><p>Titolare: Davide Davoglio, Arezzo – contatto: <a href=\"mailto:davoglio@mail.grokbot.com\">davoglio@mail.grokbot.com</a>.</p><p>Il sito non usa cookie di profilazione né tracciamento pubblicitario e non raccoglie dati personali tramite moduli. Il fornitore di hosting può trattare dati tecnici (es. indirizzo IP) nei log per sicurezza. Eventuali statistiche sono aggregate e senza cookie. In caso di futura newsletter verranno richiesti consenso esplicito (double opt-in) e fornita un'informativa specifica. Puoi esercitare i diritti previsti dagli artt. 15-22 GDPR scrivendo al titolare.</p>"), encoding="utf-8")
print(f"OK: {len(B)} bandi -> {D}")
